-- ── Ajout de l'option "Autre" au genre (Homme/Femme existants), si elle n'y est pas déjà ──
-- Resynchronise d'abord la séquence d'identité sur les données existantes : sur certains
-- environnements les lignes Homme/Femme ont été insérées avec un GenderId explicite sans
-- jamais avancer la séquence, ce qui fait échouer l'INSERT suivant avec GenderId=1 en doublon.
DO $$
DECLARE
    seq_name text;
BEGIN
    seq_name := pg_get_serial_sequence('"Genders"', 'GenderId');
    IF seq_name IS NOT NULL THEN
        PERFORM setval(seq_name, (SELECT COALESCE(MAX("GenderId"), 1) FROM "Genders"));
    END IF;

    IF NOT EXISTS (SELECT 1 FROM "Genders" WHERE "GenderName" = 'Autre') THEN
        INSERT INTO "Genders" ("GenderName") VALUES ('Autre');
    END IF;
END $$;


